export const Linspace = (start: number = -1, stop: number = 1, num: number = 100) => {
        let interval = (stop - start) / (num - 1);
    //     console.log(interval);
        let outArray = [];
        for (let i = 0; i < num; ++i) {
            outArray.push(start + (interval * i));
        }
        return outArray;
    }
