export const GenerateXYDataForTest = () => {
        return GenerateXYData(- 100, 100, 30, [0.00006, -0.003, 0.1, 10]);
    }
export const GenerateXYData = (min: number, max: number, divi: number, coeffs: number[]) => {
        const data = [];
        const interval = (max - min) / divi;
        for (let x = min; x < max; x += interval) {
            data.push([x, coeffs[0] * x * x * x + coeffs[1] * x * x + coeffs[2] * x + coeffs[3]]);
        }
        return data;
    }
    // ..................................................................................
export const GetGaussian = (x: number, mu: number, sigma: number) => {
        return Math.exp(-Math.pow(x - mu, 2.0) / (2 * Math.pow(sigma, 2.0)));
    }
export const GetGaussianForTest = () => {
        return GetGaussianEx()[1];
    }
export const GetGaussianEx = () => {
        const linspace = Linspace(-5, 5, 100);
        const inData: number[][] = [[0, 1], [0, 2], [1, 0.5], [1, 0.75]];

        const out = [];
        for (let d of inData) {
            const array = [];
            for (let x of linspace) {
                const y = GetGaussian(x, d[0], d[1]);
                array.push([x, y]);
            }
            out.push(array);
            // this.Linspace(-5, 5, 100) , this.GetGaussian(this.Linspace(-5, 5, 100), )
        }
        return out;
    }
